"""Render design samples from the same palette/metric source consumed by Android."""
import json,html,math
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
tokens=json.loads((ROOT/'android/app/src/main/res/raw/design_tokens.json').read_text())
def luminance(h):
    rgb=[int(h[i:i+2],16)/255 for i in (1,3,5)]
    return sum(c*w for c,w in zip([v/12.92 if v<=.04045 else ((v+.055)/1.055)**2.4 for v in rgb],[.2126,.7152,.0722]))
def contrast(a,b):
    x,y=sorted([luminance(a),luminance(b)])
    return (y+.05)/(x+.05)
checks=[]
for style,spec in tokens.items():
    for mode in ['light','dark']:
        c=spec[mode]
        for fg,bg in [('text','background'),('text','surface'),('muted','surface'),('muted','background'),('onAccent','action'),('onContainer','container'),('onContainer','heroEnd'),('accent','surface')]:
            ratio=contrast(c[fg],c[bg]);checks.append(f'{style}/{mode} {fg}/{bg}: {ratio:.2f}')
            assert ratio>=4.5,(style,mode,fg,bg,ratio)
(ROOT/'design/contrast-report.txt').write_text('\n'.join(checks)+'\n',encoding='utf-8')
css='''
:root{--space:16px;--board:#dfe2e8;--ink:#172032;--gap:22px;--phone:360px;--line:1px;--font:system-ui,"Microsoft YaHei",sans-serif;--round:20px;--body:16px;--caption:13px;--motion:260ms;--focus:#145bdd;--white:#fff}
*{box-sizing:border-box}body{margin:0;padding:var(--gap);background:var(--board);color:var(--ink);font:var(--body) var(--font)}h1{font-size:24px;margin:0 0 var(--space)}.note{margin-bottom:var(--gap)}.grid{display:grid;grid-template-columns:repeat(3,var(--phone));gap:var(--gap);justify-content:center}.device{background:var(--background);color:var(--text);border-radius:var(--round);overflow:hidden;padding:var(--gutter);box-shadow:0 4px 15px #17203214;min-height:760px;display:flex;flex-direction:column}.label{font-size:var(--caption);color:var(--muted);padding:12px 0}.header{display:flex;align-items:center;justify-content:space-between}h2{font-size:var(--titleSize);letter-spacing:0;margin:14px 0;font-weight:650}.action{color:var(--accent);border:0;background:var(--container);border-radius:var(--buttonRadius);padding:12px;min-height:48px;cursor:pointer}.search{display:flex;align-items:center;gap:12px;background:var(--surface);color:var(--muted);border-radius:var(--radius);padding:16px;margin:8px 0 12px}.hero{padding:16px;background:linear-gradient(120deg,var(--container),var(--heroEnd));border-radius:var(--radius);color:var(--onContainer)}.eyebrow{font-size:var(--caption);padding-bottom:14px}.hero strong{font-size:var(--titleSize)}.hero .top{display:flex;align-items:center;justify-content:space-between;margin-bottom:12px}.count{font-size:48px}.hero p{margin:0;font-size:var(--caption)}h3{font-size:var(--sectionSize);margin:22px 0 12px}.albums{display:flex;gap:12px}.album{width:calc(50% - 6px)}.art{height:124px;border-radius:var(--radius);background:linear-gradient(130deg,var(--container),var(--raised));display:grid;place-items:center;font-size:48px;color:var(--onContainer)}.album p{font-size:var(--bodySize);margin:10px 0 4px}.meta{color:var(--muted);font-size:var(--captionSize)}.row{display:flex;align-items:center;gap:12px;padding:14px 12px;background:var(--surface);border-radius:var(--radius);margin-top:8px}.row .icon{font-size:26px;color:var(--accent)}.row .words{flex:1}.words p{margin:0 0 4px}.row .arrow{color:var(--muted)}.spacer{flex:1;min-height:18px}.player{display:flex;align-items:center;gap:10px;padding:10px;background:var(--surface);border-radius:var(--radius)}.cover{width:44px;height:44px;display:grid;place-items:center;color:var(--onContainer);background:var(--container);border-radius:10px}.song{flex:1;min-width:0}.song p{margin:0 0 4px;font-size:14px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.play{background:var(--action);color:var(--onAccent);border:0;border-radius:var(--buttonRadius);width:48px;height:48px;cursor:pointer}.nav{height:var(--navHeight);display:flex;align-items:center;justify-content:space-around;font-size:var(--captionSize);color:var(--muted)}.nav span{display:flex;flex-direction:column;align-items:center;gap:4px}.nav i{font-style:normal;font-size:22px;padding:3px 16px}.nav .selected{color:var(--accent)}.MATERIAL3 .nav{background:var(--surface)}.MATERIAL3 .selected i{background:var(--container);border-radius:var(--buttonRadius)}.APPLE .hero{border-radius:var(--radius)}.APPLE .row{margin-top:0;border-radius:0;border-bottom:var(--line) solid var(--raised)}.APPLE .nav{border-top:var(--line) solid var(--raised)}button:focus-visible{outline:2px solid var(--accent);outline-offset:3px}button:active{transform:scale(.97)}button{transition:transform var(--motion)}@media(prefers-reduced-motion:reduce){button{transition:none}}@media(max-width:1100px){.grid{grid-template-columns:repeat(2,var(--phone))}}@media(max-width:750px){.grid{grid-template-columns:var(--phone)}}
'''
# All component colors reference palette variables; board-only literals are tokens too.
css=css.replace('box-shadow:0 4px 15px #17203214','box-shadow:0 4px 15px var(--board-shadow)').replace('--white:#fff','--white:#fff;--board-shadow:#17203214')
phones=[]
for mode in ['light','dark']:
    for style,spec in tokens.items():
        p=spec[mode];variables={**p,**{k:str(v)+'px' for k,v in spec.items() if isinstance(v,(int,float))}}
        aliases={'MIUIX':{'mi-primary':'accent','mi-on-primary':'onAccent','mi-surface':'surface','mi-on-surface':'text','mi-background':'background','mi-outline':'outline'},'APPLE':{'ap-tint':'accent','ap-label':'text','ap-bg':'background','ap-separator':'outline','ap-fill':'surface'},'MATERIAL3':{'md-primary':'accent','md-on-primary':'onAccent','md-surface':'surface','md-on-surface':'text','md-outline':'outline','md-error':'error'}}[style]
        variables.update({k:p[v]for k,v in aliases.items()})
        inline=';'.join('--'+k+':'+v for k,v in variables.items())
        name={'MIUIX':'MIUIX','APPLE':'Apple 音乐','MATERIAL3':'Material 3'}[style]
        page='Auralis'
        subtitle={'MIUIX':'专属音乐日签','APPLE':'MADE FOR YOU','MATERIAL3':'为今天找到节奏'}[style]
        phones.append(f'''<section class="device {style}" style="{inline}"><div class="label">{name} · {'深色'if mode=='dark'else'浅色'} · 设计样例</div><header class="header"><h2>{page}</h2><button class="action" onclick="this.closest('section').querySelector('.hero').hidden=!this.closest('section').querySelector('.hero').hidden">预览层级</button></header><div class="search">⌕　搜索歌曲、歌手或专辑</div><div class="hero"><div class="eyebrow">{subtitle}</div><div class="top"><strong>每日 30 首</strong><span class="count">{'✦'if style=='MATERIAL3'else'30'}</span></div><p>打开今天的专属歌单　›</p></div><h3>为你推荐</h3><div class="albums"><div class="album"><div class="art">♪</div><p>城市漫游</p><div class="meta">设计样例 · 非真实推荐</div></div><div class="album"><div class="art">♫</div><p>夜色与旋律</p><div class="meta">设计样例 · 非真实推荐</div></div></div><h3>你的音乐</h3><div class="row"><span class="icon">♡</span><div class="words"><p>我喜欢的音乐</p><div class="meta">音乐服务账号曲库</div></div><span class="arrow">›</span></div><div class="spacer"></div><div class="player"><div class="cover">♪</div><div class="song"><p>选择一首歌曲</p><div class="meta">音乐，随时相伴</div></div><button class="play" aria-label="预览播放按钮">▶</button></div><nav class="nav"><span class="selected"><i>⌂</i>首页</span><span><i>⌕</i>搜索</span><span><i>♙</i>我的</span></nav></section>''')
(ROOT/'design/theme-preview.html').write_text('<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Auralis · 三套主题设计预览</title><style>'+css+'</style><h1>Auralis · 三套主题 × 深浅模式</h1><p class="note">来自 Android 共用令牌的设计样例，非设备运行截图。封面与歌曲为占位示意。</p><main class="grid">'+''.join(phones)+'</main></html>',encoding='utf-8')
print('Generated six theme samples; 48 foreground/background contrast checks passed.')
